#include "execution/submit.hpp"
#include "runtime/context.hpp"
#include "runtime/dtype.hpp"
#include "runtime/owner_drain_fail_stop.hpp"
#include "runtime/runtime.hpp"
#include "runtime/tensor.hpp"

#include <algorithm>
#include <cstring>
#include <stdexcept>
#include <utility>
#include <vector>

namespace infinilm::runtime {
namespace {

void copyCpuStrided(std::byte *dst,
                    const std::byte *src,
                    const Shape &shape,
                    const Strides &dst_strides,
                    const Strides &src_strides,
                    size_t element_size,
                    size_t dim = 0) {
    if (dim == shape.size()) {
        std::memmove(dst, src, element_size);
        return;
    }

    const auto byte_size = static_cast<std::ptrdiff_t>(element_size);
    for (size_t index = 0; index < shape[dim]; ++index) {
        copyCpuStrided(
            dst + static_cast<std::ptrdiff_t>(index) * dst_strides[dim] * byte_size,
            src + static_cast<std::ptrdiff_t>(index) * src_strides[dim] * byte_size,
            shape,
            dst_strides,
            src_strides,
            element_size,
            dim + 1);
    }
}

} // namespace

Tensor TensorImpl::to(Device device) const {
    if (device == data_.memory->device()) {
        return Tensor(const_cast<TensorImpl *>(this)->shared_from_this());
    }
    auto source = allocation_owner();
    if (!source || source->device() != this->device()) {
        source = context::resolveRuntime(this->device());
    }
    auto destination = context::resolveRuntime(device);
    return to(*source, *destination);
}

Tensor TensorImpl::to(Runtime &source_runtime, Runtime &destination_runtime) const {
    source_runtime.assertOwnerThread();
    destination_runtime.assertOwnerThread();
    if (device().type() != Device::Type::kCpu && source_runtime.device() != device()) {
        throw std::invalid_argument("to Runtime and source tensor devices differ");
    }
    if (&source_runtime == &destination_runtime && device() == destination_runtime.device()) {
        return Tensor(const_cast<TensorImpl *>(this)->shared_from_this());
    }
    if (device().type() != Device::Type::kCpu && destination_runtime.device().type() == Device::Type::kCpu) {
        return to(source_runtime, destination_runtime.device());
    }
    auto result = Tensor::empty(destination_runtime, shape(), dtype());
    result->copy_from(destination_runtime, source_runtime,
                      Tensor(const_cast<TensorImpl *>(this)->shared_from_this()));
    return result;
}

Tensor TensorImpl::to(Runtime &runtime, Device target) const {
    runtime.assertOwnerThread();
    if (runtime.device() != device()) {
        throw std::invalid_argument("to Runtime and source tensor devices differ");
    }
    if (target == device()) {
        return Tensor(const_cast<TensorImpl *>(this)->shared_from_this());
    }
    if (target.type() != Device::Type::kCpu || device().type() == Device::Type::kCpu) {
        throw std::invalid_argument("explicit to only supports source-owned GPU to CPU transfer");
    }
    if (runtime.graphCaptureState() != ::infinilm::execution::graph::GraphManager::CaptureState::kInactive) {
        throw std::logic_error("D2H host observation is not allowed during graph recording");
    }
    // Host-only owning storage: do not bind a second CPU Runtime.
    auto storage = std::make_shared<std::vector<std::byte>>(nbytes());
    auto result = Tensor::from_blob(storage->data(), shape(), dtype(), target, storage);
    result->copy_from(runtime, Tensor(const_cast<TensorImpl *>(this)->shared_from_this()));
    return result;
}

void TensorImpl::copy_from(Tensor src) {
    if (!src) {
        throw std::invalid_argument("copy_from requires a source tensor");
    }
    auto source = src->allocation_owner();
    auto destination = allocation_owner();
    const bool external_gpu = !source && src->device().type() != Device::Type::kCpu
                           && device().type() != Device::Type::kCpu;
    // CPU execution is independent of a pinned allocation's accelerator owner.
    // Ownerless external data is already completed by the frontend/caller.
    if (!source || source->device() != src->device()) {
        source = context::resolveRuntime(src->device());
    }
    if (!destination || destination->device() != device()) {
        destination = context::resolveRuntime(device());
    }
    if (external_gpu) {
        if (destination->graphCaptureState() != ::infinilm::execution::graph::GraphManager::CaptureState::kInactive) {
            throw std::logic_error("completed external GPU copies are not allowed during graph recording");
        }
        try {
            copy_from(*destination, *source, src);
            destination->syncStream();
        } catch (...) {
            try {
                destination->syncStream();
            } catch (...) { detail::require_proven_owner_drain(true, false); }
            throw;
        }
    } else {
        copy_from(*destination, *source, std::move(src));
    }
}

void TensorImpl::copy_from(Runtime &destination, Runtime &source, Tensor src) {
    destination.assertOwnerThread();
    source.assertOwnerThread();
    if (!src) {
        throw std::invalid_argument("copy_from requires a source tensor");
    }
    if ((device().type() != Device::Type::kCpu && destination.device() != device())
        || (src->device().type() != Device::Type::kCpu && source.device() != src->device())) {
        throw std::invalid_argument("copy_from explicit owners and tensor devices differ");
    }
    if (src->shape() != shape() || src->dtype() != dtype()) {
        throw std::runtime_error("Cannot copy from tensor with different shape or dtype");
    }
    if (src->device().type() == Device::Type::kCpu) {
        copy_from(destination, std::move(src));
    } else if (device().type() == Device::Type::kCpu) {
        copy_from(source, std::move(src));
    } else if (&source == &destination) {
        copy_from(destination, std::move(src));
    } else {
        if (source.graphCaptureState() != ::infinilm::execution::graph::GraphManager::CaptureState::kInactive
            || destination.graphCaptureState() != ::infinilm::execution::graph::GraphManager::CaptureState::kInactive) {
            throw std::logic_error("cross-owner copies are not allowed during graph recording");
        }
        if (source.device() == destination.device()) {
            source.syncStream();
            try {
                copy_from(destination, src);
                destination.syncStream(); // Do not return src to another pool before its read completes.
            } catch (...) {
                try {
                    destination.syncStream();
                } catch (...) { detail::require_proven_owner_drain(true, false); }
                throw;
            }
        } else {
            // The existing completed D2H/H2D leaves own gather/scatter and unwind.
            auto staging = src->to(source, Device{Device::Type::kCpu});
            copy_from(destination, std::move(staging));
        }
    }
}

Tensor TensorImpl::contiguous() const {
    if (is_contiguous()) {
        return Tensor(const_cast<TensorImpl *>(this)->shared_from_this());
    } else {
        auto runtime = allocation_owner();
        const bool external_gpu = !runtime && device().type() != Device::Type::kCpu;
        if (!runtime || runtime->device() != device()) {
            runtime = context::resolveRuntime(device());
        }
        if (external_gpu) {
            if (runtime->graphCaptureState() != ::infinilm::execution::graph::GraphManager::CaptureState::kInactive) {
                throw std::logic_error("completed external GPU materialization is not allowed during graph recording");
            }
            auto source = Tensor(const_cast<TensorImpl *>(this)->shared_from_this());
            try {
                auto result = contiguous(*runtime);
                runtime->syncStream();
                return result;
            } catch (...) {
                try {
                    runtime->syncStream();
                } catch (...) { detail::require_proven_owner_drain(true, false); }
                throw;
            }
        }
        return contiguous(*runtime);
    }
}

Tensor TensorImpl::contiguous(Runtime &runtime) const {
    runtime.assertOwnerThread();
    if (runtime.device() != device()) {
        throw std::invalid_argument("contiguous runtime and tensor devices differ");
    }
    auto source = Tensor(const_cast<TensorImpl *>(this)->shared_from_this());
    if (is_contiguous()) {
        return source;
    }
    auto result = Tensor::empty(runtime, shape(), dtype());
    if (device().type() == Device::Type::kCpu) {
        // Newly allocated output cannot overlap the input: no staging needed.
        copyCpuStrided(result->data(), data(), shape(), result->strides(),
                       strides(), element_size());
    } else {
        infinilm::execution::submit<infini::ops::Copy>(
            runtime, infini::ops::Copy::DefaultConfig(runtime.device().type()),
            source, false, result);
    }
    return result;
}

void TensorImpl::copy_from(Runtime &runtime, Tensor src) {
    runtime.assertOwnerThread();
    if (!src) {
        throw std::invalid_argument("copy_from requires a source tensor");
    }
    const bool d2h = this->device().type() == Device::Type::kCpu
                  && src->device().type() != Device::Type::kCpu;
    if ((d2h && runtime.device() != src->device())
        || (!d2h && (runtime.device() != this->device() || (src->device() != this->device() && src->device().type() != Device::Type::kCpu)))) {
        throw std::invalid_argument("copy_from Runtime and tensor devices differ");
    }
    if (src->shape() != this->shape()) {
        throw std::runtime_error(
            "Cannot copy from tensor with different shape. Src: " + src->info() + " Dst: " + this->info());
    }
    if (src->dtype() != this->dtype()) {
        throw std::runtime_error(
            "Cannot copy from tensor with different dtype. Src: " + src->info() + " Dst: " + this->info());
    }

    if (d2h) {
        if (runtime.graphCaptureState() != ::infinilm::execution::graph::GraphManager::CaptureState::kInactive) {
            throw std::logic_error("D2H host observation is not allowed during graph recording");
        }
        // These resources must survive the catch-side completion proof.
        auto contiguous_src = src;
        auto destination = Tensor(const_cast<TensorImpl *>(this)->shared_from_this());
        std::vector<std::byte> gathered;
        try {
            if (!src->is_contiguous()) {
                contiguous_src = Tensor::empty(runtime, src->shape(), src->dtype());
                infinilm::execution::submit<infini::ops::Copy>(
                    runtime, infini::ops::Copy::DefaultConfig(runtime.device().type()),
                    src, false, contiguous_src);
            }
            if (this->is_contiguous()) {
                runtime.memcpyD2H(this->data(), contiguous_src->data(), this->nbytes());
            } else {
                gathered.resize(this->nbytes());
                runtime.memcpyD2H(gathered.data(), contiguous_src->data(), gathered.size());
                auto packed = Tensor::from_blob(gathered.data(), shape(), dtype(), device());
                copyCpuStrided(data(), packed->data(), shape(), strides(),
                               packed->strides(), element_size());
            }
        } catch (...) {
            try {
                runtime.syncStream();
            } catch (...) {
                detail::require_proven_owner_drain(true, false);
            }
            throw;
        }
        return;
    }

    auto dst = Tensor(const_cast<TensorImpl *>(this)->shared_from_this());
    if (this->device() == src->device()) {
        if (this->device().type() != Device::Type::kCpu) {
            infinilm::execution::submit<infini::ops::Copy>(
                runtime, infini::ops::Copy::DefaultConfig(runtime.device().type()),
                src, false, dst);
            return;
        }
        if (this->is_contiguous() && src->is_contiguous()) {
            if (this->nbytes() != 0) {
                std::memmove(this->data(), src->data(), this->nbytes());
            }
            return;
        }
        // Gather before scattering so overlapping CPU views retain the old
        // copy_from behavior without selecting a thread-local Runtime.
        std::vector<std::byte> gathered(this->nbytes());
        auto contiguous = Tensor::from_blob(
            gathered.data(), this->shape(), this->dtype(), this->device());
        copyCpuStrided(contiguous->data(), src->data(), this->shape(),
                       contiguous->strides(), src->strides(), this->element_size());
        copyCpuStrided(this->data(), contiguous->data(), this->shape(),
                       this->strides(), contiguous->strides(), this->element_size());
        return;
    }

    // Only CPU -> Runtime device crosses devices in this explicit contract.
    // Synchronize H2D before releasing a caller-owned or gathered host buffer.
    std::vector<std::byte> gathered;
    Tensor local_src;
    try {
        if (this->is_contiguous()
            && this->device().type() == Device::Type::kNvidia
            && runtime.graphCaptureState() == ::infinilm::execution::graph::GraphManager::CaptureState::kInactive
            && (src->dtype() == DataType::kFloat32
                || src->dtype() == DataType::kFloat16
                || src->dtype() == DataType::kBFloat16)
            && src->ndim() == 2 && src->shape()[0] > 1 && src->shape()[1] > 1
            && src->strides()[0] == 1 && src->strides()[1] > 0
            && static_cast<size_t>(src->strides()[1]) >= src->shape()[0]) {
            const auto span = storage_span_bytes(src->shape(), src->strides(), src->element_size());
            if (src->data_.offset > src->data_.memory->size()
                || span > src->data_.memory->size() - src->data_.offset) {
                throw std::out_of_range("strided H2D source exceeds underlying storage");
            }
            // ceil(span / 3) avoids overflowing the three-times-logical bound.
            if (span / 3 + (span % 3 != 0) <= src->nbytes()) {
                local_src = Tensor::strided_empty(runtime, src->shape(), src->strides(), src->dtype());
                runtime.memcpyH2D(local_src->data(), src->data(), span, false);
                infinilm::execution::submit<infini::ops::Copy>(
                    runtime, infini::ops::Copy::DefaultConfig(runtime.device().type()),
                    local_src, false, dst);
                runtime.syncStream(); // Keep src/dst/local_src alive through completion.
                return;
            }
        }
        const std::byte *host_data = src->data();
        if (!src->is_contiguous()) {
            gathered.resize(this->nbytes());
            auto contiguous = Tensor::from_blob(
                gathered.data(), src->shape(), src->dtype(), src->device());
            copyCpuStrided(contiguous->data(), src->data(), src->shape(),
                           contiguous->strides(), src->strides(), src->element_size());
            host_data = gathered.data();
        }
        if (this->is_contiguous()) {
            runtime.memcpyH2D(this->data(), host_data, this->nbytes(), false);
        } else {
            local_src = Tensor::empty(runtime, this->shape(), this->dtype());
            runtime.memcpyH2D(local_src->data(), host_data, this->nbytes(), false);
            infinilm::execution::submit<infini::ops::Copy>(
                runtime, infini::ops::Copy::DefaultConfig(runtime.device().type()),
                local_src, false, dst);
        }
    } catch (...) {
        // Keep host gather and device temporary alive until completion is known.
        try {
            runtime.syncStream();
        } catch (...) {
            detail::require_proven_owner_drain(true, false);
        }
        throw;
    }
}

} // namespace infinilm::runtime

#include "runtime/context.hpp"
#include "runtime/dtype.hpp"
#include "runtime/tensor.hpp"

#include "../utils.hpp"

#include <limits>
#include <spdlog/spdlog.h>
#include <sstream>
#include <stdexcept>

namespace infinilm::runtime {
namespace {
Size checked_view_numel(const Shape &shape) {
    if (std::find(shape.begin(), shape.end(), Size{0}) != shape.end()) {
        return 0;
    }
    Size result = 1;
    for (Size dim : shape) {
        if (result > std::numeric_limits<Size>::max() / dim) {
            throw std::length_error("view element count overflows");
        }
        result *= dim;
    }
    return result;
}

Stride checked_view_stride(Stride stride, Size factor) {
    if (stride < 0 || (stride != 0 && factor > static_cast<Size>(std::numeric_limits<Stride>::max() / stride))) {
        throw std::length_error("view stride overflows");
    }
    return stride == 0 ? 0 : stride * static_cast<Stride>(factor);
}

std::string shape_to_string(const Shape &shape) {
    std::ostringstream oss;
    oss << "[";
    for (size_t i = 0; i < shape.size(); ++i) {
        if (i != 0) {
            oss << ",";
        }
        oss << shape[i];
    }
    oss << "]";
    return oss.str();
}

std::string strides_to_string(const Strides &strides) {
    std::ostringstream oss;
    oss << "[";
    for (size_t i = 0; i < strides.size(); ++i) {
        if (i != 0) {
            oss << ",";
        }
        oss << strides[i];
    }
    oss << "]";
    return oss.str();
}

std::string incompatible_view_message(
    const Shape &old_shape,
    const Strides &old_strides,
    const Shape &new_shape) {
    return "Incompatible shape for view operation: old_shape="
         + shape_to_string(old_shape)
         + " old_strides=" + strides_to_string(old_strides)
         + " new_shape=" + shape_to_string(new_shape);
}
} // namespace

Tensor TensorImpl::squeeze(size_t dim) const {
    if (dim >= meta_.shape.size()) {
        throw std::out_of_range("squeeze dimension is out of range");
    }
    // Create new shape with dimension of size one removed at dim
    if (meta_.shape[dim] != 1) {
        spdlog::error("Dimension {} is not of size 1 for squeeze operation on {}.", dim, this->info());
        throw std::runtime_error("Invalid squeeze operation on tensor.");
    }
    Shape new_shape = meta_.shape;
    new_shape.erase(new_shape.begin() + dim);
    Strides new_strides = meta_.strides;
    new_strides.erase(new_strides.begin() + dim);

    auto tensor_impl = std::make_shared<TensorImpl>(new_shape, new_strides, meta_.dtype);
    tensor_impl->data_ = data_;

    return Tensor(tensor_impl);
}

Tensor TensorImpl::unsqueeze(size_t dim) const {
    if (dim > meta_.shape.size()) {
        throw std::out_of_range("unsqueeze dimension is out of range");
    }
    // Create new shape with dimension of size one inserted at dim
    Shape new_shape = meta_.shape;
    new_shape.insert(new_shape.begin() + dim, 1);

    // Create new strides with stride of zero for the new dimension
    Strides new_strides = meta_.strides;
    new_strides.insert(new_strides.begin() + dim, 0);

    auto tensor_impl = std::make_shared<TensorImpl>(new_shape, new_strides, meta_.dtype);
    tensor_impl->data_ = data_;

    return Tensor(tensor_impl);
}

Tensor TensorImpl::narrow(const std::vector<TensorSliceParams> &slices) const {
    // Create new shape and calculate offset
    Shape new_shape = meta_.shape;
    size_t offset = data_.offset;

    for (const auto &slice : slices) {
        if (slice.dim >= meta_.shape.size()
            || slice.start > meta_.shape[slice.dim]
            || slice.len > meta_.shape[slice.dim] - slice.start) {
            spdlog::error("Invalid slice [dim={}, start={}, len={}] on {}.", slice.dim, slice.start, slice.len, this->info());
            throw std::runtime_error("Invalid slice on tensor.");
        }
        new_shape[slice.dim] = slice.len;
        offset += slice.start * meta_.strides[slice.dim] * dsize(meta_.dtype);
    }

    // Create new tensor with the same strides but narrowed shape
    auto tensor_impl = std::make_shared<TensorImpl>(new_shape, meta_.strides, meta_.dtype);
    tensor_impl->data_.offset = offset;
    tensor_impl->data_.memory = data_.memory;

    return Tensor(tensor_impl);
}

Tensor TensorImpl::permute(const Shape &order) const {
    // Validate input
    INFINILM_ASSERT(meta_.shape.size() == order.size());

    // Check that order contains all indices from 0 to n-1 exactly once
    for (size_t i = 0; i < order.size(); i++) {
        INFINILM_ASSERT(std::find(order.begin(), order.end(), i) != order.end());
    }

    // Permute shape and strides
    Shape new_shape(order.size());
    Strides new_strides(order.size());

    for (size_t i = 0; i < order.size(); i++) {
        new_shape[i] = meta_.shape[order[i]];
        new_strides[i] = meta_.strides[order[i]];
    }

    auto tensor_impl = std::make_shared<TensorImpl>(new_shape, new_strides, meta_.dtype);
    tensor_impl->data_ = data_;

    return Tensor(tensor_impl);
}

Tensor TensorImpl::view(const Shape &new_shape) const {
    // Step 1: Validate total size
    const Size numel = checked_view_numel(meta_.shape);
    const Size new_numel = checked_view_numel(new_shape);
    if (numel != new_numel) {
        throw std::invalid_argument(
            incompatible_view_message(meta_.shape, meta_.strides, new_shape));
    }

    // Empty tensors have no dimensions to split; scalars have no merged
    // dimensions. Both still share the original Memory and byte offset.
    if (numel == 0 || meta_.shape.empty()) {
        if (new_shape == meta_.shape) {
            return this->as_strided(new_shape, meta_.strides);
        }
        Strides new_strides(new_shape.size());
        Stride stride = 1;
        for (size_t i = new_shape.size(); i-- > 0;) {
            new_strides[i] = stride;
            stride = checked_view_stride(stride, std::max(Size{1}, new_shape[i]));
        }
        return this->as_strided(new_shape, new_strides);
    }

    // Step 2: Get current shape and strides
    const Shape &old_shape = meta_.shape;
    const Strides &old_strides = meta_.strides;

    // Step 3: Create merged shape and strides
    Shape merged_shape;
    Strides merged_strides;

    if (!old_shape.empty()) {
        merged_shape.push_back(old_shape[0]);
        merged_strides.push_back(old_strides[0]);

        for (size_t i = 1; i < old_shape.size(); ++i) {
            if (checked_view_stride(old_strides[i], old_shape[i]) == merged_strides.back()) {
                merged_shape.back() *= old_shape[i];
                merged_strides.back() = old_strides[i];
            } else {
                merged_shape.push_back(old_shape[i]);
                merged_strides.push_back(old_strides[i]);
            }
        }
    }

    // Step 4: Compute new strides by splitting merged dimensions
    Strides new_strides(new_shape.size());
    size_t merged_idx = 0;
    Stride current_stride = merged_strides[0];
    Size remaining_size = merged_shape[0];

    for (size_t i = 0; i < new_shape.size(); ++i) {
        // Find which merged dimension contains this new dimension
        while (new_shape[i] > remaining_size) {
            if (++merged_idx >= merged_shape.size()) {
                throw std::runtime_error(
                    incompatible_view_message(old_shape, old_strides, new_shape));
            }
            current_stride = merged_strides[merged_idx];
            remaining_size = merged_shape[merged_idx];
        }

        if (remaining_size % new_shape[i] != 0) {
            throw std::runtime_error(
                incompatible_view_message(old_shape, old_strides, new_shape));
        };

        new_strides[i] = checked_view_stride(current_stride, remaining_size / new_shape[i]);
        remaining_size /= new_shape[i];
    }

    return this->as_strided(new_shape, new_strides);
}

Tensor TensorImpl::as_strided(const Shape &new_shape, const Strides &new_strides) const {
    const auto required_bytes = storage_span_bytes(
        new_shape, new_strides, dsize(meta_.dtype));
    if (data_.offset > data_.memory->size()
        || required_bytes > data_.memory->size() - data_.offset) {
        std::ostringstream message;
        message << "as_strided view exceeds the underlying storage: shape="
                << shape_to_string(shape()) << " strides=" << strides_to_string(strides())
                << " requested_shape=" << shape_to_string(new_shape)
                << " requested_strides=" << strides_to_string(new_strides)
                << " offset=" << data_.offset << " span=" << required_bytes
                << " storage=" << data_.memory->size();
        throw std::out_of_range(message.str());
    }
    auto tensor_impl = std::make_shared<TensorImpl>(new_shape, new_strides, meta_.dtype);
    tensor_impl->data_ = data_;

    return Tensor(tensor_impl);
}
} // namespace infinilm::runtime

#include "runtime.hpp"
#include "owner_drain_fail_stop.hpp"

#include "runtime/utils.hpp"

#include <infini/rt/device_guard.h>

#include <atomic>
#include <cstdint>
#include <exception>
#include <limits>
#include <stdexcept>

namespace infinilm::runtime {
namespace {

uint64_t allocateOwnerGeneration() noexcept {
    static std::atomic<uint64_t> next_generation{1};
    auto candidate = next_generation.load(std::memory_order_relaxed);
    for (;;) {
        // Never wrap the counter: even a concurrent allocation cannot reuse
        // generation 1 while another thread is terminating on exhaustion.
        if (candidate == 0 || candidate == std::numeric_limits<uint64_t>::max()) {
            std::terminate();
        }
        if (next_generation.compare_exchange_weak(
                candidate, candidate + 1, std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return candidate;
        }
    }
}

uint64_t currentOwnerGeneration() noexcept {
    static thread_local const uint64_t generation = allocateOwnerGeneration();
    return generation;
}

void warn_runtime_cleanup_failure(const char *operation, infini::rt::runtime::Error status) noexcept {
    if (status == infini::rt::runtime::kSuccess) {
        return;
    }
    try {
        spdlog::warn("{} failed during Runtime cleanup with error code {}",
                     operation,
                     static_cast<long long>(status));
    } catch (...) {
    }
}

void warn_runtime_cleanup_failure(const char *operation, const char *detail) noexcept {
    try {
        spdlog::warn("{} failed during Runtime cleanup: {}", operation, detail);
    } catch (...) {
    }
}

} // namespace

std::shared_ptr<Runtime> Runtime::create(Device device) {
    if (device.index() < 0 || static_cast<size_t>(device.index()) >= context::getDeviceCount(device.type())) {
        throw std::invalid_argument("device index is unavailable for the requested backend");
    }
    infini::rt::DeviceGuard guard{device.type(), device.index(), true};
    return std::shared_ptr<Runtime>(new Runtime(device));
}

Runtime::Runtime(Device device) : device_(device), owner_generation_(currentOwnerGeneration()), graph_manager_(std::make_unique<::infinilm::execution::graph::GraphManager>()) {
    try {
        device_memory_allocator_ = std::make_unique<infini::rt::ReusableMemoryPool>(device);
        // Borrow the RT-owned execution stream. Pin leases retain its state;
        // Runtime never independently destroys this queue.
        stream_ = device_memory_allocator_->stream();
    } catch (...) {
        device_memory_allocator_.reset();
        stream_ = nullptr;
        throw;
    }
}
Runtime::~Runtime() noexcept {
    infini::rt::DeviceGuard device_guard{device_.type(), device_.index()};

    try {
        if (stream_ != nullptr) {
            const auto synchronize_status = infini::rt::runtime::StreamSynchronize(stream_);
            warn_runtime_cleanup_failure("synchronizing the runtime stream", synchronize_status);
        }
    } catch (const std::exception &error) {
        warn_runtime_cleanup_failure("synchronizing the runtime stream", error.what());
    } catch (...) {
        warn_runtime_cleanup_failure("synchronizing the runtime stream", "unknown error");
    }

    graph_manager_.reset();
    device_memory_allocator_.reset();
    stream_ = nullptr; // Pool state drains/frees/destroys after its last lease.
}

Runtime *Runtime::activate() {
    INFINILM_ASSERT(device_.type() != infini::rt::Device::Type::kCount);
    infini::rt::set_runtime_device_type(device_.type());
    INFINILM_CHECK_ERROR(infini::rt::runtime::SetDevice(device_.index()));
    return this;
}

void Runtime::assertOwnerThread() const {
    if (currentOwnerGeneration() != owner_generation_) {
        throw std::runtime_error("Runtime execution belongs to another worker thread");
    }
}

Device Runtime::device() const {
    return device_;
}

infini::rt::runtime::Stream Runtime::stream() const {
    return stream_;
}

void Runtime::enableOwnerDrainFailStop() {
    assertOwnerThread();
    owner_drain_fail_stop_ = true;
}
void Runtime::drainBeforeHostCopyUnwind() noexcept {
    if (!owner_drain_fail_stop_) {
        return;
    }
    try {
        assertOwnerThread();
        infini::rt::DeviceGuard guard{device_.type(), device_.index(), true};
        const auto status = infini::rt::runtime::StreamSynchronize(stream());
        detail::require_proven_owner_drain(true, status == infini::rt::runtime::kSuccess);
    } catch (...) { detail::require_proven_owner_drain(true, false); }
}
void Runtime::syncStream() {
    try {
        infini::rt::DeviceGuard device_guard{device_.type(), device_.index(), true};
        const auto status = infini::rt::runtime::StreamSynchronize(stream());
        detail::require_proven_owner_drain(owner_drain_fail_stop_, status == infini::rt::runtime::kSuccess);
        INFINILM_CHECK_ERROR(status);
    } catch (...) {
        detail::require_proven_owner_drain(owner_drain_fail_stop_, false);
        throw;
    }
}

void Runtime::syncDevice() {
    infini::rt::DeviceGuard device_guard{device_.type(), device_.index(), true};
    INFINILM_CHECK_ERROR(infini::rt::runtime::DeviceSynchronize());
}

void Runtime::syncStreamForCleanup() noexcept {
    infini::rt::DeviceGuard device_guard{device_.type(), device_.index()};
    if (device_guard.active()) {
        try {
            if (stream_ != nullptr) {
                const auto synchronize_status = infini::rt::runtime::StreamSynchronize(stream_);
                warn_runtime_cleanup_failure("synchronizing the graph runtime stream", synchronize_status);
            }
        } catch (const std::exception &error) {
            warn_runtime_cleanup_failure("synchronizing the graph runtime stream", error.what());
        } catch (...) {
            warn_runtime_cleanup_failure("synchronizing the graph runtime stream", "unknown error");
        }
    }
}

void Runtime::trimMemory() {
    infini::rt::DeviceGuard device_guard{device_.type(), device_.index(), true};
    device_memory_allocator_->trim();
}

size_t Runtime::graphPinnedMemoryBytes() {
    assertOwnerThread();
    return device_memory_allocator_->pinned_bytes();
}

void Runtime::releaseDeviceMemory(std::byte *ptr) noexcept {
    bool release_is_safe = true;
    // Reuse on the owning worker remains ordered on this Runtime's stream.
    // A foreign thread must wait for already-submitted work before returning
    // the block to the pool; synchronizing the whole device is unnecessary.
    if (device_.type() != Device::Type::kCpu
        && currentOwnerGeneration() != owner_generation_) {
        infini::rt::DeviceGuard device_guard{device_.type(), device_.index()};
        if (device_guard.active()) {
            const auto status = infini::rt::runtime::StreamSynchronize(stream_);
            warn_runtime_cleanup_failure("synchronizing a foreign-thread allocation release", status);
            release_is_safe = status == infini::rt::runtime::kSuccess;
        } else {
            release_is_safe = false;
        }
    }

    if (release_is_safe) {
        try {
            device_memory_allocator_->deallocate(ptr);
        } catch (const std::exception &error) {
            warn_runtime_cleanup_failure("releasing device memory", error.what());
        } catch (...) {
            warn_runtime_cleanup_failure("releasing device memory", "unknown error");
        }
    }
}

std::shared_ptr<Memory> Runtime::allocateMemory(size_t size) {
    infini::rt::DeviceGuard device_guard{device_.type(), device_.index(), true};
    auto runtime = shared_from_this();
    std::byte *data_ptr = runtime->device_memory_allocator_->allocate(size);
    try {
        return std::make_shared<Memory>(
            data_ptr, size, device_,
            [runtime](std::byte *p) { runtime->releaseDeviceMemory(p); },
            false, size > 0, runtime); // Zero allocations have no allocator block to pin.
    } catch (...) {
        runtime->device_memory_allocator_->deallocate(data_ptr);
        throw;
    }
}

std::shared_ptr<Memory> Runtime::allocateParameterMemory(size_t size) {
    infini::rt::DeviceGuard device_guard{device_.type(), device_.index(), true};
    auto runtime = shared_from_this();
    std::byte *data_ptr = runtime->device_memory_allocator_->allocate_exact(size);
    try {
        return std::make_shared<Memory>(
            data_ptr, size, device_,
            [runtime](std::byte *p) { runtime->releaseDeviceMemory(p); },
            false, true, runtime);
    } catch (...) {
        runtime->device_memory_allocator_->deallocate(data_ptr);
        throw;
    }
}

std::shared_ptr<Memory> Runtime::allocatePinnedHostMemory(size_t size) {
    infini::rt::DeviceGuard device_guard{device_.type(), device_.index(), true};
    if (device_.type() == Device::Type::kCpu) {
        spdlog::warn("For CPU devices, pinned memory is not supported, falling back to regular host memory");
        return allocateMemory(size);
    }
    auto runtime = shared_from_this();
    void *data_ptr = nullptr;
    if (size != 0) {
        INFINILM_CHECK_ERROR(infini::rt::runtime::MallocHost(&data_ptr, size));
    }
    try {
        return std::make_shared<Memory>(
            static_cast<std::byte *>(data_ptr), size, Device{Device::Type::kCpu},
            [runtime](std::byte *p) {
                infini::rt::DeviceGuard guard{runtime->device_.type(), runtime->device_.index()};
                if (!guard.active() || p == nullptr) {
                    return;
                }
                try {
                    INFINILM_CHECK_ERROR(infini::rt::runtime::FreeHost(p));
                } catch (const std::exception &error) {
                    warn_runtime_cleanup_failure("releasing pinned host memory", error.what());
                } catch (...) {
                    warn_runtime_cleanup_failure("releasing pinned host memory", "unknown error");
                }
            },
            true, false, runtime);
    } catch (...) {
        if (data_ptr != nullptr) {
            INFINILM_CHECK_ERROR(infini::rt::runtime::FreeHost(data_ptr));
        }
        throw;
    }
}

std::shared_ptr<Memory> Runtime::reinstantiateBlob(std::shared_ptr<Memory> blob) {
    assertOwnerThread();
    if (!blob || blob->device() != device_) {
        throw std::invalid_argument("graph blob belongs to another runtime device");
    }
    auto runtime = shared_from_this();
    auto ptr = blob->data();
    // Every resumed view has its own logical span. The allocator's Block
    // use_count is the shared physical lease, incremented once per view and
    // decremented once by that view's Memory deleter.
    const auto block_size = device_memory_allocator_->retain_allocation(ptr);
    try {
        if (blob->size() > block_size) {
            throw std::out_of_range("graph blob exceeds its allocator block");
        }
        return std::make_shared<Memory>(
            ptr, blob->size(), device_,
            [runtime](std::byte *p) { runtime->releaseDeviceMemory(p); },
            false, true, runtime);
    } catch (...) {
        runtime->releaseDeviceMemory(ptr);
        throw;
    }
}

bool Runtime::retainGraphMemory(const std::shared_ptr<Memory> &memory) {
    assertOwnerThread();
    if (!memory || memory->device() != device_) {
        throw std::runtime_error(
            "graph capture cannot retain memory from a different device");
    }
    return device_memory_allocator_->retain_for_capture(memory->data());
}

void Runtime::memcpyH2D(void *dst, const void *src, size_t size, bool async) {
    try {
        infini::rt::DeviceGuard device_guard{device_.type(), device_.index(), true};
        if (device_.type() == Device::Type::kCpu) {
            INFINILM_CHECK_ERROR(infini::rt::runtime::Memcpy(dst, src, size, infini::rt::runtime::kMemcpyHostToDevice));
            return;
        }

        const auto current_stream = stream();
        INFINILM_CHECK_ERROR(
            infini::rt::runtime::MemcpyAsync(dst, src, size, infini::rt::runtime::kMemcpyHostToDevice, current_stream));
        if (!async) {
            syncStream();
        }
    } catch (...) {
        drainBeforeHostCopyUnwind(); // before deep host buffer destructors
        throw;
    }
}

void Runtime::memcpyD2H(void *dst, const void *src, size_t size) {
    try {
        infini::rt::DeviceGuard device_guard{device_.type(), device_.index(), true};
        if (device_.type() == Device::Type::kCpu) {
            INFINILM_CHECK_ERROR(infini::rt::runtime::Memcpy(dst, src, size, infini::rt::runtime::kMemcpyDeviceToHost));
            return;
        }

        const auto current_stream = stream();
        INFINILM_CHECK_ERROR(
            infini::rt::runtime::MemcpyAsync(dst, src, size, infini::rt::runtime::kMemcpyDeviceToHost, current_stream));
        syncStream();
    } catch (...) {
        drainBeforeHostCopyUnwind(); // before deep host buffer destructors
        throw;
    }
}

void Runtime::memcpyD2D(void *dst, const void *src, size_t size, bool async) {
    infini::rt::DeviceGuard device_guard{device_.type(), device_.index(), true};
    if (device_.type() == Device::Type::kCpu) {
        INFINILM_CHECK_ERROR(infini::rt::runtime::Memcpy(dst, src, size, infini::rt::runtime::kMemcpyDeviceToDevice));
        return;
    }

    const auto current_stream = stream();
    INFINILM_CHECK_ERROR(
        infini::rt::runtime::MemcpyAsync(dst, src, size, infini::rt::runtime::kMemcpyDeviceToDevice, current_stream));
    if (!async) {
        INFINILM_CHECK_ERROR(infini::rt::runtime::StreamSynchronize(current_stream));
    }
}

void Runtime::setDeviceMemory(void *ptr, int value, size_t count) {
    infini::rt::DeviceGuard device_guard{device_.type(), device_.index(), true};
    if (device_.type() == Device::Type::kCpu) {
        INFINILM_CHECK_ERROR(infini::rt::runtime::Memset(ptr, value, count));
        return;
    }

    const auto current_stream = stream();
    INFINILM_CHECK_ERROR(infini::rt::runtime::MemsetAsync(ptr, value, count, current_stream));
    INFINILM_CHECK_ERROR(infini::rt::runtime::StreamSynchronize(current_stream));
}

void Runtime::setDeviceMemoryAsync(void *ptr, int value, size_t count, infini::rt::runtime::Stream stream) {
    infini::rt::DeviceGuard device_guard{device_.type(), device_.index(), true};
    if (device_.type() != Device::Type::kCpu) {
        if (stream == nullptr) {
            stream = this->stream();
        }
        INFINILM_CHECK_ERROR(infini::rt::runtime::MemsetAsync(ptr, value, count, stream));
    } else {
        INFINILM_CHECK_ERROR(infini::rt::runtime::Memset(ptr, value, count));
    }
}

