    if (should_exit_) {
        if (failure_) {
            std::rethrow_exception(failure_);
        }
        throw std::runtime_error("RankWorker is closing; cannot run");
    }

    pending_args_ = args;
    job_cmd_ = Command::RUN;
    has_job_ = true;
    job_done_ = false;

    cv_.notify_all();
}

